#!/usr/bin/env python3
"""Export only bounded JSON files generated by this controlled fixture, never raw receipts.
Not a general untrusted-file exporter. No recursion or ancestor symlinks allowed.
"""
import os,stat
from pathlib import Path

def directory(p):
 p=Path(p)
 for q in [p,*p.parents]:
  st=q.lstat()
  if not stat.S_ISDIR(st.st_mode) or q.is_symlink():raise RuntimeError('export-directory-unsafe')
 if p.resolve()!=p.absolute():raise RuntimeError('export-directory-resolution')
 return p

def export(source=Path('/tmp/held-update-proof'),base=Path('/tmp/systemd-export')):
 if os.geteuid()!=0:raise RuntimeError('export-root-required')
 directory(source);directory(base.parent)
 # Fresh root-owned container, never overwrite or reuse a user's target path.
 base.mkdir(mode=0o755,exist_ok=False);directory(base)
 dest=base/'evidence';dest.mkdir(mode=0o700);directory(dest)
 names={'execution-evidence.json','delivery-receipt.json','closed-helper-fixture-failure.json','systemd-failure.json'}
 paths=[source/n for n in names];child=source/'held-update'
 try:child.lstat()
 except FileNotFoundError:pass
 else:
  directory(child)
  entries=list(child.iterdir())
  if len(entries)>64:raise RuntimeError('export-too-many-entries')
  paths += [p for p in entries if p.suffix=='.json' and p.name.startswith(('scenario-','systemd-cleanup-','systemd-start-failure-'))]
 if len(paths)>32:raise RuntimeError('export-too-many-files')
 for p in paths:
  try:fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
  except FileNotFoundError:continue
  try:
   st=os.fstat(fd)
   if not stat.S_ISREG(st.st_mode) or st.st_nlink!=1 or st.st_size>1048576:raise RuntimeError('export-file-unsafe')
   data=os.read(fd,1048577)
   if len(data)>1048576:raise RuntimeError('export-file-too-large')
   target=dest/p.name
   out=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o644)
   try:os.write(out,data)
   finally:os.close(out)
  finally:os.close(fd)
 dest.chmod(0o755)

if __name__=='__main__':export()
